const test = require('node:test');
const assert = require('node:assert/strict');
const { reconocerImagen, comprobarDestino } = require('../src/services/comprobante-lector.service');
// Synthetic receipt, no customer image. OCR uses only bundled language files.
const image = 'data:image/png;base64,';

test('real backend OCR accepts matching recipient and rejects another destination', async () => {
  const titular = process.env.PAGOS_TITULAR, suffix = process.env.PAGOS_DESTINO_ULTIMOS4;
  process.env.PAGOS_TITULAR = 'MARIA DEL ROCIO BAHENA JUAREZ';
  process.env.PAGOS_DESTINO_ULTIMOS4 = '4409';
  const payload = { comprobanteData: image, folioOperacion: '0452579754', fechaOperacion: '2026-10-08', horaOperacion: '12:49', monto: 300 };
  try {
    const result = await comprobarDestino(payload);
    assert.match(result.texto, /4409/);
    await assert.rejects(comprobarDestino({ ...payload, monto: 350 }), { status: 422 });
    process.env.PAGOS_DESTINO_ULTIMOS4 = '5511';
    await assert.rejects(comprobarDestino(payload), { status: 422 });
  } finally {
    if (titular === undefined) delete process.env.PAGOS_TITULAR; else process.env.PAGOS_TITULAR = titular;
    if (suffix === undefined) delete process.env.PAGOS_DESTINO_ULTIMOS4; else process.env.PAGOS_DESTINO_ULTIMOS4 = suffix;
  }
});

test('invalid images and oversize input are rejected before OCR', async () => {
  await assert.rejects(reconocerImagen('https://example.com/image.png'), { status: 400 });
  await assert.rejects(reconocerImagen('data:image/png;base64,' + Buffer.alloc(1200001).toString('base64')), { status: 413 });
});

test('OCR failure releases capacity and refuses unverified proof', async () => {
  await assert.rejects(reconocerImagen('data:image/png;base64,YWJj'), { status: 503 });
  const result = await reconocerImagen(image);
  assert.match(result, /4409/);
});

test('capacity and deadline stop workers and allow subsequent requests', async () => {
  const vm = require('node:vm');
  const fs = require('node:fs');
  const { EventEmitter } = require('node:events');
  const workers = [], timers = [];
  class FakeWorker extends EventEmitter {
    constructor() { super(); this.stopped = false; workers.push(this); }
    async terminate() { this.stopped = true; this.emit('exit', 1); }
  }
  const sandbox = {
    require: name => name === 'node:worker_threads' ? { Worker: FakeWorker } : name === './comprobante-parser' ? require('../src/services/comprobante-parser') : require(name),
    module: { exports: {} }, __dirname: require('node:path').join(__dirname, '../src/services'),
    Buffer, process, setTimeout: callback => { timers.push(callback); return timers.length; }, clearTimeout() {}
  };
  vm.runInNewContext(fs.readFileSync(require.resolve('../src/services/comprobante-lector.service'), 'utf8'), sandbox);
  const read = sandbox.module.exports.reconocerImagen;
  const a = read(image), b = read(image);
  await assert.rejects(read(image), { status: 503 });
  const failed = assert.rejects(a, { status: 503 });
  timers[0]();
  await failed;
  assert.equal(workers[0].stopped, true);
  workers[1].emit('message', { ok: true, text: 'received' });
  assert.equal(await b, 'received');
  const c = read(image);
  workers[2].emit('message', { ok: true, text: 'another' });
  assert.equal(await c, 'another');
});
